import React, { useRef } from 'react';
import * as RadixTooltip from '@radix-ui/react-tooltip';
import { truncateText } from '@/lib/scilent/utils/metadata';

/**
 * Props for the MetadataLabel component
 */
export interface MetadataLabelProps {
  /**
   * Text content to display
   */
  text: string;

  /**
   * Whether to truncate the text when it exceeds maxLength
   * @default true
   */
  truncate?: boolean;

  /**
   * Type of truncation to apply
   * @default "end"
   */
  truncationType?: 'none' | 'end' | 'middle';

  /**
   * Maximum number of characters before truncation
   * @default undefined (no truncation unless specified)
   */
  maxLength?: number;

  /**
   * HTML element to render as
   * @default "span"
   */
  as?: 'span' | 'div' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';

  /**
   * Additional CSS class name
   */
  className?: string;

  /**
   * Additional inline styles
   * Use this for all styling needs (fontWeight, fontStyle, color, fontSize, etc.)
   */
  style?: React.CSSProperties;

  /**
   * Click handler
   */
  onClick?: (event: React.MouseEvent<HTMLElement>) => void;

  /**
   * Additional HTML attributes
   */
  [key: string]: any;
}

/**
 * MetadataLabel component for displaying text with truncation options
 *
 * @example
 * // Basic usage
 * <MetadataLabel text="Some text content" />
 *
 * @example
 * // With truncation
 * <MetadataLabel
 *   text="A very long text that will be truncated"
 *   truncate={true}
 *   truncationType="middle"
 *   maxLength={20}
 * />
 *
 * @example
 * // With custom styling
 * <MetadataLabel
 *   text="Styled text"
 *   style={{ fontWeight: 'bold', fontStyle: 'italic', color: '#1DB954', fontSize: '18px' }}
 * />
 */
export const MetadataLabel: React.FC<MetadataLabelProps> = ({
  text,
  truncate = true,
  truncationType = 'end',
  maxLength,
  as = 'span',
  className = '',
  style = {},
  onClick,
  ...rest
}) => {
  const textRef = useRef<HTMLElement>(null);

  // Apply truncation if needed
  let displayText = text;
  let isTruncated = false;

  if (truncate && maxLength && text.length > maxLength) {
    displayText = truncateText(text, maxLength, truncationType);
    isTruncated = true;
  }

  // Combine styles
  const combinedStyles: React.CSSProperties = {
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    ...style,
  };

  // Create the component based on the 'as' prop
  const Component = as;

  // If truncated, wrap in tooltip to show full text
  if (isTruncated) {
    return (
      <RadixTooltip.Provider>
        <RadixTooltip.Root>
          <RadixTooltip.Trigger asChild>
            <Component
              ref={textRef as React.Ref<HTMLDivElement>}
              className={`metadata-label ${className}`}
              style={combinedStyles}
              onClick={onClick}
              data-full-text={text}
              {...rest}
            >
              {displayText}
            </Component>
          </RadixTooltip.Trigger>
          <RadixTooltip.Portal>
            <RadixTooltip.Content
              className="metadata-label-tooltip"
              sideOffset={5}
              style={{
                backgroundColor: 'rgba(0, 0, 0, 0.8)',
                color: 'white',
                borderRadius: '4px',
                padding: '8px 12px',
                fontSize: '14px',
                maxWidth: '300px',
                zIndex: 1000,
              }}
            >
              {text}
              <RadixTooltip.Arrow style={{ fill: 'rgba(0, 0, 0, 0.8)' }} />
            </RadixTooltip.Content>
          </RadixTooltip.Portal>
        </RadixTooltip.Root>
      </RadixTooltip.Provider>
    );
  }

  // If not truncated, render normally
  return (
    <Component
      ref={textRef as React.Ref<HTMLDivElement>}
      className={`metadata-label ${className}`}
      style={combinedStyles}
      onClick={onClick}
      data-full-text={text}
      {...rest}
    >
      {displayText}
    </Component>
  );
};

export default MetadataLabel;

import React, { useState, useEffect, useRef } from 'react';
import * as Primitive from '@radix-ui/react-primitive';
import styled, { css, keyframes } from 'styled-components';
import type { TimestampVariant, TimestampSize, TimestampFormat } from '@/lib/scilent/types';
import { formatDuration, formatRelativeTime, formatDateTime } from './utils';

export interface TimestampProps {
  /**
   * The value to display, can be:
   * - number (seconds for duration, milliseconds for date)
   * - Date object
   * - ISO string
   */
  value: number | Date | string;

  /**
   * The variant of the timestamp
   * @default 'default'
   */
  variant?: TimestampVariant;

  /**
   * The size of the timestamp
   * @default 'md'
   */
  size?: TimestampSize;

  /**
   * The format to display the timestamp in
   * @default 'duration' for numbers, 'relative' for dates
   */
  format?: TimestampFormat;

  /**
   * Custom format string for date/time (follows Intl.DateTimeFormat options)
   * Only used when format is 'custom'
   */
  customFormat?: Intl.DateTimeFormatOptions;

  /**
   * Custom locale for formatting
   * @default system locale
   */
  locale?: string;

  /**
   * Whether to animate changes
   * @default false
   */
  animate?: boolean;

  /**
   * Whether to update relative times automatically
   * @default true for relative format
   */
  autoUpdate?: boolean;

  /**
   * Update interval in milliseconds for relative times
   * @default 60000 (1 minute)
   */
  updateInterval?: number;

  /**
   * Additional CSS class name
   */
  className?: string;

  /**
   * Additional inline styles for the root element
   */
  style?: React.CSSProperties;
}

// Animation for smooth transitions
const fadeChange = keyframes`
  0% {
    opacity: 0.5;
    transform: translateY(2px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
`;

// Define the styled timestamp component
const StyledTimestamp = styled(Primitive.Primitive.span)<{
  $variant: TimestampVariant;
  $size: TimestampSize;
  $animate: boolean;
}>`
  display: inline-flex;
  align-items: center;
  font-family: var(--font-mono, monospace);
  transition: color 150ms ease;

  ${props =>
    props.$animate &&
    css`
      &.timestamp-changed {
        animation: ${fadeChange} 300ms ease-out;
      }
    `}

  /* Size variants */
  ${props =>
    props.$size === 'sm' &&
    css`
      font-size: 12px;
    `}

  ${props =>
    props.$size === 'md' &&
    css`
      font-size: 14px;
    `}

  ${props =>
    props.$size === 'lg' &&
    css`
      font-size: 16px;
    `}

  /* Style variants */
  ${props =>
    props.$variant === 'default' &&
    css`
      color: var(--color-text, #111827);
    `}

  ${props =>
    props.$variant === 'muted' &&
    css`
      color: var(--color-text-muted, #6b7280);
    `}

  ${props =>
    props.$variant === 'highlight' &&
    css`
      color: var(--color-primary, #3b82f6);
      font-weight: 500;
    `}

  ${props =>
    props.$variant === 'contrast' &&
    css`
      color: var(--color-text-contrast, #ffffff);
      text-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
    `}
`;

/**
 * Timestamp component for displaying various time-related information
 *
 * Supports durations, relative times, and formatted dates/times
 */
export const Timestamp = React.forwardRef<HTMLSpanElement, TimestampProps>(
  (
    {
      value,
      variant = 'default',
      size = 'md',
      format,
      customFormat,
      locale = navigator.language,
      animate = false,
      autoUpdate = true,
      updateInterval = 60000, // 1 minute
      className = '',
      style = {},
      ...props
    },
    ref
  ) => {
    const [displayValue, setDisplayValue] = useState<string>('');
    const [isChanged, setIsChanged] = useState<boolean>(false);
    const prevValueRef = useRef<string>('');

    // Determine the default format based on the value type
    const determineFormat = (): TimestampFormat => {
      if (format) return format;

      if (typeof value === 'number') {
        return 'duration';
      } else {
        return 'relative';
      }
    };

    const actualFormat = determineFormat();

    // Format the value based on its type and the specified format
    const formatValue = () => {
      try {
        // Handle number values (assumed to be seconds for duration)
        if (typeof value === 'number') {
          if (actualFormat === 'duration') {
            return formatDuration(value, value >= 3600);
          } else {
            // Treat number as timestamp in milliseconds
            const date = new Date(value);
            return formatDateTime(date, actualFormat, locale, customFormat);
          }
        }

        // Handle Date objects
        if (value instanceof Date) {
          if (actualFormat === 'relative') {
            return formatRelativeTime(value, locale);
          } else {
            return formatDateTime(value, actualFormat, locale, customFormat);
          }
        }

        // Handle string values (assumed to be ISO date strings)
        if (typeof value === 'string') {
          const date = new Date(value);
          if (isNaN(date.getTime())) {
            return value; // If not a valid date, just return the string
          }

          if (actualFormat === 'relative') {
            return formatRelativeTime(date, locale);
          } else {
            return formatDateTime(date, actualFormat, locale, customFormat);
          }
        }

        return String(value);
      } catch (error) {
        console.error('Error formatting timestamp:', error);
        return String(value);
      }
    };

    // Update the displayed value
    useEffect(() => {
      const newValue = formatValue();
      setDisplayValue(newValue);

      // Check if the value has changed for animation
      if (animate && prevValueRef.current && prevValueRef.current !== newValue) {
        setIsChanged(true);
        const timer = setTimeout(() => setIsChanged(false), 300);
        return () => clearTimeout(timer);
      }

      prevValueRef.current = newValue;
    }, [value, actualFormat, locale, customFormat]);

    // Set up auto-updating for relative times
    useEffect(() => {
      if (autoUpdate && actualFormat === 'relative' && updateInterval > 0) {
        const intervalId = setInterval(() => {
          setDisplayValue(formatValue());
        }, updateInterval);

        return () => clearInterval(intervalId);
      }
    }, [value, actualFormat, autoUpdate, updateInterval]);

    return (
      <StyledTimestamp
        ref={ref}
        as="span"
        $variant={variant}
        $size={size}
        $animate={animate}
        className={`timestamp ${isChanged ? 'timestamp-changed' : ''} ${className}`}
        style={style}
        {...props}
      >
        {displayValue}
      </StyledTimestamp>
    );
  }
);

Timestamp.displayName = 'Timestamp';

/**
 * Timestamp utility functions for use throughout the application
 */

/**
 * Format a duration in seconds to MM:SS or HH:MM:SS format
 *
 * @param seconds - Duration in seconds
 * @param showHours - Whether to always show hours (even if 0)
 * @returns Formatted duration string
 */
export const formatDuration = (seconds: number, showHours = false): string => {
  if (isNaN(seconds) || seconds < 0) return '00:00';

  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  if (showHours || hours > 0) {
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

/**
 * Format a date to a relative time string (e.g., "2 days ago")
 *
 * @param date - Date to format
 * @param locale - Locale to use for formatting
 * @returns Relative time string
 */
export const formatRelativeTime = (date: Date, locale = 'en'): string => {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const isFuture = diffMs < 0;
  const absDiffMs = Math.abs(diffMs);

  // Calculate time differences in various units
  const diffSec = Math.floor(absDiffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);

  // More accurate month and year calculations
  const nowMonth = now.getMonth() + now.getFullYear() * 12;
  const dateMonth = date.getMonth() + date.getFullYear() * 12;
  const diffMonth = Math.abs(nowMonth - dateMonth);

  const diffYear = Math.floor(diffMonth / 12);

  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
  const sign = isFuture ? 1 : -1;

  if (diffSec < 60) {
    return rtf.format(sign * diffSec, 'second');
  } else if (diffMin < 60) {
    return rtf.format(sign * diffMin, 'minute');
  } else if (diffHour < 24) {
    return rtf.format(sign * diffHour, 'hour');
  } else if (diffDay < 30) {
    return rtf.format(sign * diffDay, 'day');
  } else if (diffMonth < 12) {
    return rtf.format(sign * diffMonth, 'month');
  } else {
    return rtf.format(sign * diffYear, 'year');
  }
};

/**
 * Calculate total duration of tracks in seconds
 *
 * @param trackDurations - Array of track durations in seconds
 * @returns Total duration in seconds
 */
export const calculateTotalDuration = (trackDurations: number[]): number => {
  return trackDurations.reduce((total, duration) => total + duration, 0);
};

/**
 * Format a date using Intl.DateTimeFormat with common music-related presets
 *
 * @param date - Date to format
 * @param format - Format preset to use
 * @param locale - Locale to use for formatting
 * @param customOptions - Custom Intl.DateTimeFormat options (for 'custom' format)
 * @returns Formatted date string
 */
export const formatDateTime = (
  date: Date,
  format:
    | 'date'
    | 'time'
    | 'datetime'
    | 'shortDate'
    | 'shortTime'
    | 'shortDatetime'
    | 'yearMonth'
    | 'monthDay'
    | 'weekday'
    | 'relative'
    | 'duration'
    | 'custom' = 'datetime',
  locale = 'en',
  customOptions?: Intl.DateTimeFormatOptions
): string => {
  // Handle special formats that don't use Intl.DateTimeFormat
  if (format === 'relative') {
    return formatRelativeTime(date, locale);
  }

  if (format === 'duration') {
    // For duration format, interpret the date's time in seconds
    const seconds = Math.floor(date.getTime() / 1000);
    return formatDuration(seconds);
  }

  if (format === 'custom' && customOptions) {
    return new Intl.DateTimeFormat(locale, customOptions).format(date);
  }

  const options: Record<string, Intl.DateTimeFormatOptions> = {
    date: { year: 'numeric', month: 'short', day: 'numeric' },
    time: { hour: 'numeric', minute: 'numeric' },
    datetime: {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
    },
    shortDate: { month: 'numeric', day: 'numeric', year: '2-digit' },
    shortTime: { hour: 'numeric', minute: 'numeric' },
    shortDatetime: { month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' },
    yearMonth: { year: 'numeric', month: 'long' },
    monthDay: { month: 'long', day: 'numeric' },
    weekday: { weekday: 'long' },
    // Fallbacks for special formats (should not be used due to early returns above)
    relative: { year: 'numeric', month: 'short', day: 'numeric' },
    duration: { hour: 'numeric', minute: 'numeric', second: 'numeric' },
    custom: { year: 'numeric', month: 'short', day: 'numeric' },
  };

  return new Intl.DateTimeFormat(locale, options[format] || options.datetime).format(date);
};

/**
 * Convert milliseconds to seconds
 *
 * @param ms - Time in milliseconds
 * @returns Time in seconds
 */
export const msToSeconds = (ms: number): number => {
  return Math.floor(ms / 1000);
};

/**
 * Convert seconds to milliseconds
 *
 * @param seconds - Time in seconds
 * @returns Time in milliseconds
 */
export const secondsToMs = (seconds: number): number => {
  return seconds * 1000;
};

/**
 * Format a duration in a human-readable way (e.g., "2h 15m" or "45m 30s")
 *
 * @param seconds - Duration in seconds
 * @returns Human-readable duration string
 */
export const formatDurationHuman = (seconds: number): string => {
  if (isNaN(seconds) || seconds < 0) return '0s';

  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  const parts = [];

  if (hours > 0) {
    parts.push(`${hours}h`);
  }

  if (minutes > 0 || (hours > 0 && secs > 0)) {
    parts.push(`${minutes}m`);
  }

  if (secs > 0 || (hours === 0 && minutes === 0)) {
    parts.push(`${secs}s`);
  }

  return parts.join(' ');
};

import { MetadataLabelProps } from '@/components/scilent/metadata-label/MetadataLabel';

/**
 * Truncation options for text elements
